#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int  gr,fr;  EDirect eDir;  TRIVERTEX vert[4];  } Queue_Volume;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(TRIVERTEX& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void GradientRectangle( HDC hDC, TRIVERTEX* vert, int nGrad, EDirect eDir, int nFrame )  {  //  RECT rect;  ::SetRect(&rect,vert[0].x,vert[0].y,vert[3].x,vert[3].y);  //  if ( nGrad != 1 )    {    COLORREF color = RGB( vert[1].Red  >>8,                          vert[1].Green>>8,                          vert[1].Blue >>8);    HBRUSH h1 = ::CreateSolidBrush(color);    if ( h1 )      {      ::FillRect( hDC, &rect, h1 );      ::DeleteObject( h1 );      }    }  //  static GRADIENT_RECT  gRect = {0,1};  DWORD dwMode = ( eDir == dirVert )?GRADIENT_FILL_RECT_H:GRADIENT_FILL_RECT_V;  ::GradientFill(hDC,&vert[0],2,&gRect,1,dwMode);  if ( nGrad != 1 )  ::GradientFill(hDC,&vert[2],2,&gRect,1,dwMode);  //  if ( nFrame > 0  )    ::FrameRect( hDC, &rect, (HBRUSH)::GetStockObject(BLACK_BRUSH));  else  if ( nFrame == 0 )    {    CMyPen pen( hDC, 0 );    //    ::MoveToEx( hDC, rect.left, rect.top, NULL );    if ( eDir == dirVert )      ::LineTo ( hDC, rect.left, rect.bottom );    else      ::LineTo ( hDC, rect.right, rect.top );    //    ::MoveToEx( hDC, rect.right, rect.bottom, NULL );    if ( eDir == dirVert )      ::LineTo ( hDC, rect.right, rect.top );    else      ::LineTo ( hDC, rect.left, rect.bottom );    //    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintVolume(DefinePaint)  {  QueueP(Queue_Volume);  GradientRectangle( hDC, p->vert, p->gr, p->eDir, p->fr );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddVolume(DefineTegs)  {  AddQueueEx(Queue_Volume);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintVolume;  //  COLORREF fon   = 0xfffffe;//0-фон  COLORREF light = 0x888887;//1-свет  COLORREF dark  = 0x888887;//2-тьма  p->gr = 2;  RECT rect;  //  STegObj obj[] =    {    { 'R', "rect"  , &rect  },    { 'E', "rc"    , &rect  },    { 'A', "fon"   , &fon   },    { 'A', "light" , &light },    { 'A', "dark"  , &dark  },    { 'A', "f"     , &fon   },    { 'A', "l"     , &light },    { 'A', "d"     , &dark  },    { 'I', "frame" , &p->fr },    { 'I', "g"     , &p->gr },    { 'I', "grad"  , &p->gr },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->eDir = ParserDirect(teg[0].value);  //  SetT(p->vert[0],light);  SetT(p->vert[1],fon  );  SetT(p->vert[2],fon  );  SetT(p->vert[3],dark );  //  p->vert[0].x = rect.left;p->vert[1].x = rect.right;  p->vert[2].x = rect.left;p->vert[3].x = rect.right;  p->vert[0].y = rect.top ;p->vert[1].y = rect.bottom;  p->vert[2].y = rect.top ;p->vert[3].y = rect.bottom;  //  if ( p->gr != 1 )    {    if ( p->eDir == dirVert )      {      int part = (rect.right-rect.left)/p->gr;      p->vert[1].x = rect.left +part;      p->vert[2].x = rect.right-part;      }    else      {      int part = (rect.bottom-rect.top)/p->gr;      p->vert[1].y = rect.top+part;      p->vert[2].y = rect.bottom-part;      }    }  ::SetRect(&p->mRect,p->vert[0].x,p->vert[0].y,p->vert[3].x,p->vert[3].y);  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~